/*
  Import: Process Auto Quote in ForAgentsOnly.com
  Source: Tango workflow (imported 2026-09-04)
  Run this once in Supabase SQL Editor to create this SOP as a pending
  step-by-step walkthrough. It shows up in Admin -> Pending Reviews for
  approval before it's visible in the VA portal.

  Self-contained: adds the step-by-step content columns/function itself
  first (safe to re-run - IF NOT EXISTS / CREATE OR REPLACE throughout),
  so this works standalone even if 00_full_schema.sql was never run.
*/

ALTER TABLE sop_content
  ADD COLUMN IF NOT EXISTS content_type text NOT NULL DEFAULT 'text' CHECK (content_type IN ('text', 'steps')),
  ADD COLUMN IF NOT EXISTS steps jsonb,
  ADD COLUMN IF NOT EXISTS images jsonb;

-- Postgres won't let CREATE OR REPLACE change a function's output columns,
-- so this always drops it first - safe since nothing else depends on it.
DROP FUNCTION IF EXISTS search_sops(uuid, text);
CREATE FUNCTION search_sops(
  p_company_id uuid,
  p_query text
)
RETURNS TABLE (
  document_id uuid,
  title text,
  line_of_business text,
  process_category text,
  version text,
  content text,
  content_type text,
  steps jsonb,
  images jsonb,
  insurance_company_name text
)
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT
    d.id,
    d.title,
    d.line_of_business,
    d.process_category,
    d.version,
    c.content,
    c.content_type,
    c.steps,
    c.images,
    ic.name
  FROM sop_documents d
  JOIN sop_content c ON c.sop_document_id = d.id
  JOIN insurance_companies ic ON ic.id = d.insurance_company_id
  WHERE d.insurance_company_id = p_company_id
    AND d.status = 'published'
    AND (
      d.title ILIKE '%' || p_query || '%'
      OR d.process_category ILIKE '%' || p_query || '%'
      OR d.line_of_business ILIKE '%' || p_query || '%'
      OR c.content ILIKE '%' || p_query || '%'
    )
  ORDER BY d.title;
$$;

INSERT INTO insurance_companies (name) VALUES ('Progressive')
ON CONFLICT (name) DO NOTHING;

WITH company AS (
  SELECT id FROM insurance_companies WHERE name = 'Progressive'
), doc AS (
  INSERT INTO sop_documents (insurance_company_id, title, line_of_business, process_category, version, status)
  SELECT id, 'Process Auto Quote in ForAgentsOnly.com', 'Personal Lines', 'Auto Quote', '1.0', 'pending'
  FROM company
  RETURNING id
)
INSERT INTO sop_content (sop_document_id, content, content_type, steps)
SELECT id, $tango_content$Process Auto Quote in ForAgentsOnly.com
In this tutorial, you'll learn how to quote an auto policy in Progressive.
1. Click on Select Product(s)
2. Click on AUTO
3. Click on Add Products to Quote
4. Start by entering the client's first name. 
5. Type in the client's last name. 
6. Type the client's date of birth.
7. Select the client's gender.
8. Type the client's email.
9. Type the client's phone number. 
10. Proceed to current mailing address. 
11. Type the client's address
12. Type the city.
13. Type the ZIP Code. 
14. Identify if the client moved to the mailing address stated in the last 2 months. Select No if they did not move in the last 2 months, and Yes if otherwise. 
15. Select Yes to proceed. 
16. Click on PRODUCTS
17. Type the date when the client wants the policy to take effect. 
18. Type the vehicle identification number (VIN). 
19. Click on Search icon to reveal the vehicle's make, model, and year. 
20. Click on VIN
21. Identify how long does the client owned the vehicle. 
22. Select the vehicle's primary use.
23. Identify if the vehicle is used for Ridesharing, etc. 
24. Identify if the vehicle is used for delivery. 
25. Click on HOUSEHOLD MEMBERS
26. identify the client's marital status. 
27. Select the client's highest level of education. 
28. Select the client's employment.
29. Select the client's occupation/job position. 
30. Identify the type of driver's license the client has. 
31. Select the license's status. 
32. Select the client's license state.
33. Type the client's drivers license. 
34. Identify the age when the client first got their drivers license. 
35. Identify if the client has an international license and for how long. 
36. Click on ADDITIONAL DETAILS
37. Read the questions at the left part of the Auto Details section and provide the answer. The questions are just answerable by Yes and No. 
38. Identify the client's primary residence. 
39. Identify if the client wants to bundle their quote with other business. If the client only wants an auto quote, check No additional risks apply.
40. Click on COVERAGES/BILL PLANS
41. Enter the client's desired coverage/deductible/limits.
42. Identify if the client wants to get enrolled in Snapshot to get discount. 
43. Click on Recalculate
44. This shows the premium offer before the reports are run. To get the near accurate premium offer, we'll have to run the reports first then go back to this page afterwards. 
45. Click on PORTFOLIO
46. Uncheck MVR (Used in Auto/Toys). Running  the MVR report might cause your agency to be charged. 
47. Click on ORDER POINT OF SALE to run the CLUE report. 
48. Click on CONTINUE
49. Click on PORTFOLIO to get back on the coverages page for the near accurate premium offer. 
50. Below is the new premium offer after the CLUE report is run. 
51. Click on Options
52. Click on Print/Email/Fax.
